CREATE OR REPLACE FUNCTION public.audit_log_trigger()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id UUID;
  v_project UUID;
  v_old JSONB;
  v_new JSONB;
  v_action TEXT;
BEGIN
  -- Try to get the current user; might be NULL for service-role operations.
  BEGIN
    v_user_id := auth.uid();
  EXCEPTION WHEN OTHERS THEN
    v_user_id := NULL;
  END;

  IF TG_OP = 'DELETE' THEN
    v_action := 'DELETE';
    v_old    := to_jsonb(OLD);
    v_new    := NULL;
    v_project := OLD.project_id;
  ELSIF TG_OP = 'UPDATE' THEN
    v_action := 'UPDATE';
    v_old    := to_jsonb(OLD);
    v_new    := to_jsonb(NEW);
    v_project := NEW.project_id;
  ELSE
    v_action := 'INSERT';
    v_old    := NULL;
    v_new    := to_jsonb(NEW);
    v_project := NEW.project_id;
  END IF;

  -- Existing audit rows are intentionally project-scoped and project_id is
  -- NOT NULL. If the parent project no longer exists, there is no valid audit
  -- parent to attach to; returning here keeps the user operation from failing.
  IF v_project IS NULL OR NOT EXISTS (
    SELECT 1
    FROM public.projects p
    WHERE p.id = v_project
  ) THEN
    IF TG_OP = 'DELETE' THEN
      RETURN OLD;
    END IF;
    RETURN NEW;
  END IF;

  INSERT INTO public.pma_audit_logs (
    project_id, entity_type, entity_id, action,
    old_values, new_values, changed_by
  ) VALUES (
    v_project,
    TG_TABLE_NAME,
    CASE WHEN TG_OP = 'DELETE' THEN OLD.id ELSE NEW.id END,
    v_action,
    v_old,
    v_new,
    v_user_id::TEXT
  );

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.update_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  new.updated_at = now();
  return new;
end;
$function$

